class Solution { public int countMatchingSubarrays(int[] nums,int[] pattern){int[] prefix=new int[pattern.length];for(int i=1,matched=0;i<pattern.length;i++){while(matched>0&&pattern[i]!=pattern[matched])matched=prefix[matched-1];if(pattern[i]==pattern[matched])matched++;prefix[i]=matched;}int answer=0,matched=0;for(int i=1;i<nums.length;i++){int relation=Integer.compare(nums[i],nums[i-1]);while(matched>0&&relation!=pattern[matched])matched=prefix[matched-1];if(relation==pattern[matched])matched++;if(matched==pattern.length){answer++;matched=prefix[matched-1];}}return answer;} }
